{
  "name": "@juliuskb/opencode-voice",
  "version": "0.0.9",
  "description": "Local-first voice dictation for OpenCode with push-to-talk Whisper transcription",
  "opencodeVoice": {
    "releases": {
      "0.0.1": [
        "First public release of local push-to-talk dictation for OpenCode.",
        "Added local Whisper transcription, model management, editable draft forms, settings, and recovery."
      ],
      "0.0.2": [
        "Fixed the TUI failing to load from a clean npm installation because the host selected the React JSX runtime."
      ],
      "0.0.3": [
        "Fixed the installed-package panel rendering only its initial state by shipping a precompiled reactive panel.",
        "Added recorder cleanup/watchdogs and blocked transcription when the configured model is missing.",
        "Aligned plugin identifiers with the published package name."
      ],
      "0.0.4": [
        "Added measured performance guidance and an Unload model from memory action."
      ],
      "0.0.5": [
        "Fixed model unload leaking native workers and memory under OpenCode's bundled Bun 1.4.2."
      ],
      "0.0.6": [
        "Fixed the VAD reset crash between independent takes.",
        "Added a scrollable viewer for current and previous logs.",
        "Model unload now closes settings and reloads cleanly on the next take."
      ],
      "0.0.7": [
        "Shows the installed OpenCode Voice version in the panel.",
        "Checks daily for newer releases and announces each available version once.",
        "Adds update availability and complete release notes without installing anything."
      ],
      "0.0.8": [
        "Adds an Update channel setting (Advanced → Debug): the npm dist-tag the update check follows, verified against npm when entered.",
        "Adds an About entry to the menu with the version and the project's GitHub and npm pages.",
        "Recommended VAD minimum silence is now 0.8 s (was 0.4), which avoids isolated one-word lines; a saved 0.4 is kept and marked with * in the menu — reset to defaults or change it yourself."
      ],
      "0.0.9": [
        "Long phrases are now cut at real pauses before the decode ceiling, which removes duplicated words and stray periods at the cut.",
        "Lines made only of filler words (uh, um, hmm…) are dropped; the list is a setting in the new Cleanup group, so other languages can use their own, and off disables it.",
        "Model downloads are checked first: a missing tar or bzip2 and an unwritable model directory are named before anything is fetched, low disk space asks before starting, the progress bar says when it is extracting, and only the needed files leave the archive, which halves the disk space an install needs.",
        "Verified on OpenCode 2.1.1."
      ]
    }
  },
  "type": "module",
  "scripts": {
    "check": "tsc -p tsconfig.json",
    "test": "bun test",
    "build": "bun run scripts/build-tui.ts",
    "prepack": "bun run build >/dev/null",
    "prepublishOnly": "bun run check && bun test"
  },
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./dist/tui.js",
    "./rpc": "./src/rpc.ts"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.31",
    "sherpa-onnx-node": "1.13.8"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17 <0.7.0",
    "@opentui/solid": ">=0.5.17 <0.7.0",
    "solid-js": ">=1.9.0 <2.0.0"
  },
  "license": "MIT",
  "author": "JuliusKB",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JuliusKB/opencode-voice.git"
  },
  "homepage": "https://github.com/JuliusKB/opencode-voice#readme",
  "bugs": {
    "url": "https://github.com/JuliusKB/opencode-voice/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "voice",
    "dictation",
    "speech-to-text",
    "whisper",
    "sherpa-onnx"
  ],
  "files": [
    "src",
    "dist",
    "index.ts",
    "tui.ts",
    "rpc.ts",
    "tsconfig.json",
    "LICENSE",
    "README.md"
  ],
  "devDependencies": {
    "@opentui/core": "0.6.6",
    "@opentui/solid": "0.6.6",
    "@types/bun": "^1.4.3",
    "solid-js": "1.9.12",
    "typescript": "^5.9.3"
  }
}
